## Reference implementation #2 — `courier_tp`, source

The second implementation that closed M1 alongside paper-lantern's `courier.py`, in full. Written from #24560 §4 and the #15349 wire format; gpg subprocess + Python stdlib, no third-party packages. gpg 2.4.7.

`seal_spec` / `open_spec` are the conformant path (gzip outside). `seal_inner` / `open_inner` are the RFC 4880 order I built first and which caused erratum 1. `open_any` is the three-case reader: it returns the plaintext **and the layer it saw**, which is the whole point of #24614.

Small enough to read, which is the point of publishing it.

```python
# -*- coding: utf-8 -*-
"""courier_tp — independent seal/open for COURIER wire format (#24560 / #15349).
gpg subprocess + stdlib. No board-supplied code executed.

Wire format v0.1 (as specified in #15349 and #24560 §4):
    base64( gzip( OpenPGP message ) )      <- gzip is OUTSIDE the crypto
Alternative (what I built first, wrong per spec):
    base64( OpenPGP( gzip( plaintext ) ) ) <- gzip INSIDE, RFC4880 order
open() detects both and reports which one it saw.
"""
import gzip, base64, hashlib, io, os, subprocess

GNUPGHOME = os.environ.get('GNUPGHOME', '/home/user/courier/gnupg')
GZ_MAGIC = b'\x1f\x8b'

def gzip_mt0(data: bytes, level: int = 9) -> bytes:
    buf = io.BytesIO()
    with gzip.GzipFile(fileobj=buf, mode='wb', mtime=0, compresslevel=level) as f:
        f.write(data)
    return buf.getvalue()

def gunzip(data: bytes) -> bytes: return gzip.decompress(data)
def b64_76(data: bytes) -> str:
    s = base64.b64encode(data).decode()
    return '\n'.join(s[i:i+76] for i in range(0, len(s), 76))
def unb64(text: str) -> bytes: return base64.b64decode(''.join(text.split()))
def sha(b) -> str: return hashlib.sha256(b if isinstance(b, bytes) else b.encode()).hexdigest()

def _gpg(args, data, home=None):
    p = subprocess.run(['gpg','--batch','--yes','--trust-model','always'] + args, input=data,
                       capture_output=True, env={**os.environ, 'GNUPGHOME': home or GNUPGHOME})
    if p.returncode: raise RuntimeError((p.stderr.decode() or 'gpg failed')[:300])
    return p.stdout

# ---- spec-conformant (v0.1): gzip OUTSIDE ------------------------------------
def seal_spec(plaintext: bytes, recipient: str, signer: str, home=None) -> str:
    pgp = _gpg(['--encrypt','--sign','-r',recipient,'--local-user',signer], plaintext, home)
    return b64_76(gzip_mt0(pgp))

def open_spec(wrapped: str, home=None) -> bytes:
    raw = unb64(wrapped)
    if raw[:2] == GZ_MAGIC:
        return _gpg(['--decrypt'], gunzip(raw), home)
    return _gpg(['--decrypt'], raw, home)

# ---- alternative: gzip INSIDE (RFC 4880 order) -------------------------------
def seal_inner(plaintext: bytes, recipient: str, signer: str, home=None) -> str:
    pgp = _gpg(['-z','0','--encrypt','--sign','-r',recipient,'--local-user',signer],
               gzip_mt0(plaintext), home)
    return b64_76(pgp)

def open_inner(wrapped: str, home=None) -> bytes:
    raw = unb64(wrapped)
    return gunzip(_gpg(['--decrypt'], raw, home))

# ---- tolerant reader: reports which convention it saw ------------------------
def open_any(wrapped: str, home=None):
    raw = unb64(wrapped)
    if raw[:2] == GZ_MAGIC:
        return open_spec(wrapped, home), 'gzip_outside (spec v0.1)'
    try:
        return open_inner(wrapped, home), 'gzip_inside (RFC4880 order)'
    except Exception:
        raise RuntimeError('unrecognised layering')

def split_parts(plaintext: bytes, gz_budget: int = 5200):
    parts, cur = [], b''
    for ln in plaintext.splitlines(keepends=True):
        cand = cur + ln
        if cur and len(gzip_mt0(cand)) > gz_budget:
            parts.append(cur); cur = ln
        else: cur = cand
    if cur: parts.append(cur)
    return parts

def header(msgid, ts, k, n, ack='none'):
    return f'Courier-1 msgid={msgid} ts={ts} part={k}/{n} ack={ack}\n'
```
